public class Program {

public static void main(String[] args) throws Exception {
final class BinKey {
    private final String zone;
    private final int slot;
    BinKey(String zone, int slot) {
        this.zone = zone;
        this.slot = slot;
    }
    @Override public boolean equals(Object other) {
        if (this == other) return true;
        if (other == null || getClass() != other.getClass()) return false;
        BinKey that = (BinKey) other;
        return slot == that.slot && java.util.Objects.equals(zone, that.zone);
    }
    @Override public int hashCode() {
        return java.util.Objects.hash(zone, slot);
    }
}
BinKey a = new BinKey("east", 4), b = new BinKey("east", 4), c = new BinKey("east", 4);
if (a == b || !a.equals(b) || !b.equals(a) || !b.equals(c) || !a.equals(c)) throw new AssertionError("equivalence");
if (a.equals(null) || a.equals("east") || a.equals(new BinKey("west", 4)) || a.equals(new BinKey("east", 5))) throw new AssertionError("different fields");
if (!a.equals(a) || a.hashCode() != b.hashCode() || !a.equals(b)) throw new AssertionError("consistency");
var keys = new java.util.HashSet<BinKey>(); keys.add(a); keys.add(b);
if (keys.size() != 1 || !keys.contains(c)) throw new AssertionError("key contract");
if (!new BinKey(null, 2).equals(new BinKey(null, 2))) throw new AssertionError("nullable field");
System.out.println("equality contracts verified");
}
}

