public class Program {
record CountRow(String name, int count) {}
static java.util.List<CountRow> parse(java.io.Reader source)
        throws java.io.IOException {
    var reader = new java.io.BufferedReader(source);
    var rows = new java.util.ArrayList<CountRow>();
    String line;
    int lineNumber = 0;
    while ((line = reader.readLine()) != null) {
        lineNumber++;
        String[] fields = line.split("\\|", -1);
        try {
            if (fields.length != 2 || fields[0].trim().isEmpty())
                throw new IllegalArgumentException("Expected name|count");
            int count = Integer.parseInt(fields[1].trim());
            if (count < 0) throw new IllegalArgumentException("Negative count");
            rows.add(new CountRow(fields[0].trim(), count));
        } catch (IllegalArgumentException failure) {
            throw new java.io.IOException("Malformed row " + lineNumber, failure);
        }
    }
    return rows;
}
static void write(java.io.Writer target, java.util.List<CountRow> rows)
        throws java.io.IOException {
    for (CountRow row : rows) {
        target.write(row.name() + "=" + row.count() + "\n");
    }
}
public static void main(String[] args) throws Exception {

class TrackingReader extends java.io.StringReader {
    boolean closed;
    TrackingReader(String text) { super(text); }
    @Override public void close() { closed = true; super.close(); }
}
var reader = new TrackingReader("cedar|0\nmaple|12\n");
var rows = parse(reader);
if (!rows.equals(java.util.List.of(new CountRow("cedar",0),new CountRow("maple",12))) || reader.closed) throw new AssertionError("model/ownership");
reader.close();
for (String bad : new String[]{"", "x", "x|", "x|-1", "x|abc", "|4", "x|4|tail"}) {
    try { parse(new java.io.StringReader("valid|2\n"+bad+"\n")); throw new AssertionError("accepted malformed input"); }
    catch (java.io.IOException expected) { if (!expected.getMessage().equals("Malformed row 2")) throw new AssertionError(expected); }
}
if (!parse(new java.io.StringReader("")).isEmpty()) throw new AssertionError("empty file");
java.io.Reader failing = new java.io.Reader() {
    public int read(char[] buffer,int offset,int length) throws java.io.IOException { throw new java.io.IOException("read failed"); }
    public void close() {}
};
try { parse(failing); throw new AssertionError("lost read failure"); }
catch (java.io.IOException expected) { if (!expected.getMessage().equals("read failed")) throw new AssertionError(expected); }
var target = new java.io.StringWriter(); write(target, rows);
System.out.print(target.toString());
var empty = new java.io.StringWriter(); write(empty, java.util.List.of());
if (!empty.toString().isEmpty()) throw new AssertionError("empty report");
var brokenTarget = new java.io.Writer() {
    public void write(char[] b,int o,int l) throws java.io.IOException { throw new java.io.IOException("write failed"); }
    public void flush() {} public void close() {}
};
try { write(brokenTarget, rows); throw new AssertionError("lost write failure"); }
catch (java.io.IOException expected) { if (!expected.getMessage().equals("write failed")) throw new AssertionError(expected); }
var owned = new TrackingReader("bad|x");
try (owned) { parse(owned); throw new AssertionError("bad row passed"); }
catch (java.io.IOException expected) { if (!owned.closed) throw new AssertionError("not closed on failure"); }
System.out.println("malformed, I/O and ownership checks verified");

}
}

