public static void main(String[] args) throws Exception {
record Slot(String aisle, int position) implements Comparable<Slot> {
    @Override public int compareTo(Slot other) {
        int aisleOrder = aisle.compareTo(other.aisle);
        return aisleOrder != 0 ? aisleOrder : Integer.compare(position, other.position);
    }
}
var slots = new java.util.ArrayList<>(java.util.List.of(new Slot("B",1),new Slot("A",8),new Slot("A",2)));
java.util.Collections.sort(slots);
System.out.println(slots);
if (new Slot("A",Integer.MIN_VALUE).compareTo(new Slot("A",Integer.MAX_VALUE)) >= 0) throw new AssertionError("overflow");
record Bucket(java.util.List<String> entries) {}
var list = new java.util.ArrayList<String>(); var bucket = new Bucket(list); list.add("changed");
if (bucket.entries().size()!=1) throw new AssertionError("record was assumed deeply immutable");

}
}

public class Program {

public static void main(String[] args) throws Exception {
class Counter {
    private int count;
    synchronized void increment() { count++; }
    synchronized int value() { return count; }
}
Counter counter = new Counter();
Runnable work = () -> {
    for (int i = 0; i < 4; i++) counter.increment();
};
Thread first = new Thread(work);
Thread second = new Thread(work);
first.start();
second.start();
first.join();
second.join();
System.out.println(counter.value());
}
}
